// 冷准入核固定八种定义、原人物/文本/真实操练挑战引用；完整profile配对由唯一World选择。
#include "military_tactic_learning_catalog.hpp"
#include "military_officer_codec.hpp"
#include "resident/domains/conditions/domain_codec_util.hpp"
namespace hanmo::resident {
Outcome<MilitaryTacticLearningCatalog> decode_military_tactic_learning_catalog(const BoundaryValue& v,const BoundaryValue& data){
 try{auto checked=military_officer_codec::validate_json_unique_keys(v);if(!checked.ok)return {false,{},checked.error};const StableId path="military_tactic_learning";boundary::fields(v,{"version","definitions","initial_grants"},{},path);if(boundary::get_int(v,"version",path)!=1)boundary::fail("MilitaryTacticLearningProfileMismatch",path);MilitaryTacticLearningCatalog out;out.enabled=true;
 auto exists=[&](const StableId& table,const StableId& id){const auto* rows=data.find(table);return rows&&rows->find(id);};
 for(const auto& row:boundary::array(boundary::field(v,"definitions",path),path)){boundary::fields(row,{"id","name_key","description_key","kind","teacher_actor_ids","practice_challenge_ids","practice_min_score"},{},path);MilitaryLearnedTacticDefinition d;d.id=boundary::get_string(row,"id",path);d.name_key=boundary::get_string(row,"name_key",path);d.description_key=boundary::get_string(row,"description_key",path);auto k=military_learned_tactic_kind(boundary::get_string(row,"kind",path));if(!k.ok)return {false,{},k.error};d.kind=k.value;d.teacher_actor_ids=boundary::strings(boundary::field(row,"teacher_actor_ids",path),path);d.practice_challenge_ids=boundary::strings(boundary::field(row,"practice_challenge_ids",path),path);d.practice_min_score=boundary::get_int(row,"practice_min_score",path);if(!exists("texts",d.name_key)||!exists("texts",d.description_key))boundary::fail("MilitaryTacticDefinitionTextRequired",d.id);for(const auto& actor:d.teacher_actor_ids)if(!exists("actors",actor))boundary::fail("MilitaryTacticTeacherUnknown",actor);for(const auto& challenge:d.practice_challenge_ids)if(!exists("drill_challenges",challenge))boundary::fail("MilitaryTacticPracticeChallengeUnknown",challenge);out.definitions.push_back(std::move(d));}
 for(const auto& row:boundary::array(boundary::field(v,"initial_grants",path),path)){boundary::fields(row,{"id","actor_id","tactic_id"},{},path);MilitaryTacticInitialGrant g;g.id=boundary::get_string(row,"id",path);g.actor_id=boundary::get_string(row,"actor_id",path);g.tactic_id=boundary::get_string(row,"tactic_id",path);if(!exists("actors",g.actor_id))boundary::fail("MilitaryTacticInitialActorRequired",g.actor_id);out.initial_grants.push_back(std::move(g));}checked=validate_military_tactic_learning_catalog(out);return checked.ok?Outcome<MilitaryTacticLearningCatalog>{true,std::move(out),{}}:Outcome<MilitaryTacticLearningCatalog>{false,{},checked.error};
 }catch(const boundary::DecodeFailure& e){return {false,{},e.error};}
}
}
